#include <bits/stdc++.h>
using namespace std;
using ll = long long;

#define _P(...) (void)printf(__VA_ARGS__)
#define FOR(i,n) for(int i=0;i<(n);++i)
#define FORR(i,arr) for(auto& i:arr)
#define FORR2(i,j,arr) for(auto& [i,j]:arr)
#define ALL(a) (a).begin(),(a).end()
#define ZERO(a) memset(a,0,sizeof(a))
#define MINUS(a) memset(a,-1,sizeof(a))
template<class T> bool chmax(T &a, const T &b) { if(a<b){a=b;return 1;}return 0;}
template<class T> bool chmin(T &a, const T &b) { if(a>b){a=b;return 1;}return 0;}

ll MOD;
struct modint {
    ll val;
    modint(ll v=0) : val(v) { if(MOD && (val>=MOD || val<0)) val = (val%MOD+MOD)%MOD; }

    static modint mod_pow(const modint& base, ll exp) {
        ll b = base.val, res = 1;
        while(exp) {
            if(exp & 1) res = res * b % MOD;
            b = b * b % MOD;
            exp >>= 1;
        }
        return modint(res);
    }

    modint& operator+=(const modint& other) { val += other.val; if(val >= MOD) val -= MOD; return *this; }
    modint& operator-=(const modint& other) { val = (val - other.val + MOD) % MOD; return *this; }
    modint& operator*=(const modint& other) { val = val * other.val % MOD; return *this; }
    modint& operator/=(const modint& other) { assert(other.val != 0); *this *= mod_pow(other, MOD-2); return *this; }

    modint operator+(const modint& other) const { modint res(*this); return res += other; }
    modint operator-(const modint& other) const { modint res(*this); return res -= other; }
    modint operator*(const modint& other) const { modint res(*this); return res *= other; }
    modint operator/(const modint& other) const { modint res(*this); return res /= other; }

    friend ostream& operator<<(ostream& os, const modint& m) { os << m.val; return os; }
};

int N, M;
modint dp1[505];
modint dp2[505];
modint dp3[505][505];
modint dp4[505][505];

ll nCr(ll n, ll r) {
    const int MAX = 400001;
    static ll fact[MAX], inv_fact[MAX], inv[MAX];
    if(fact[0] == 0) {
        inv[1] = fact[0] = inv_fact[0] = 1;
        for(int i = 2; i <= MAX; ++i) {
            inv[i] = inv[MOD % i] * (MOD - MOD / i) % MOD;
        }
        for(int i = 1; i <= MAX; ++i) {
            fact[i] = fact[i-1] * i % MOD;
            inv_fact[i] = inv_fact[i-1] * inv[i] % MOD;
        }
    }
    if(r < 0 || r > n) return 0;
    return inv_fact[r] * fact[n] % MOD * inv_fact[n-r] % MOD;
}

void solve() {
    cin >> N >> M >> MOD;

    dp1[0] = 1;
    for(int i = 1; i <= N; ++i) {
        for(int j = 1; j <= i; ++j) {
            dp1[i] += modint(i+1) * dp1[j-1] * dp1[i-j] * nCr(i-1, j-1);
            dp2[i] += modint(i+1) * (dp2[i-j] * dp1[j-1] + dp1[i-j] * dp2[j-1]) * nCr(i-1, j-1);
            dp2[i] += dp1[j-1] * dp1[i-j] * nCr(i-1, j-1) * (nCr(j, 2) + nCr(i-j+1, 2));
        }
    }

    dp3[0][0] = 1;
    for(int i = 1; i <= N; ++i) {
        for(int j = 0; j < i; ++j) {
            dp3[i][j] = dp3[i-1][j];
            dp4[i][j] = dp4[i-1][j];
            for(int l = 1; l <= j; ++l) {
                dp3[i][j] += dp1[l] * dp3[i-l-1][j-l] * nCr(j, l);
                dp4[i][j] += (dp1[l] * dp4[i-l-1][j-l] + dp2[l] * dp3[i-l-1][j-l]) * nCr(j, l);
            }
        }
        dp3[i][i] = dp1[i];
        dp4[i][i] = dp2[i];
    }

    cout << dp4[N][M] << endl;
}

int main(int argc, char** argv) {
    string s;
    if(argc == 1) {
        ios::sync_with_stdio(false);
        cin.tie(nullptr);
    }
    for(int i = 1; i < argc; ++i) {
        s += argv[i];
        s += '\n';
    }
    reverse(s.begin(), s.end());
    for(char c : s) ungetc(c, stdin);
    cout.tie(nullptr);
    solve();
    return 0;
}
